#include <stdio.h>

int main(void)
{
    int a[] = {2, 4, 6};
    int sum = 0;
    for (size_t i = 0; i < 3; i++) { sum += a[i]; }
    printf("%.1f\n", sum / 3.0);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[2][2] = {{1, 2}, {3, 4}};
    for (size_t r = 0; r < 2; r++) {
        int sum = 0;
        for (size_t c = 0; c < 2; c++) { sum += a[r][c]; }
        printf("%d\n", sum);
    }
    return 0;
}

